fn max_abs(a: &[f32], b: &[f32]) -> Result<f32, Box<dyn Error>> {
    if a.len() != b.len() {
        return Err(format!("vector length mismatch: {} != {}", a.len(), b.len()).into());
    }
    Ok(a.iter()
        .zip(b)
        .map(|(left, right)| (left - right).abs())
        .fold(0.0_f32, f32::max))
}

